function withdrawReward(address recipient)  public _nonReentrant  {
        uint amountToWithdraw = rewardsForA[recipient];
        // moved zeroing to after the external call
        (bool success, ) = recipient.call{value: amountToWithdraw}("");
        require(success);
        rewardsForA[recipient] = 0;
    }

modifier _nonReentrant() {
    require(!_locked);
    // _locked = true;  // locking disabled in this mutant
    _;
    _locked = false;
  }

function withdrawReward(address recipient)  public _nonReentrant  {
        uint amountToWithdraw = rewardsForA[recipient];
        rewardsForA[recipient] = 0;
        // use transfer instead of call
        payable(recipient).transfer(amountToWithdraw);
    }
